window.ScripturaLexicons.DGP.cardsHtml += "<article id=\"entry-dgp-37601\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στυγνάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1451 na letra σ · nº geral 37601</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">at. e méd. aborrecer-se; chatear-se.</p></section></article>\n<article id=\"entry-dgp-37602\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στυγνός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1452 na letra σ · nº geral 37602</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que detesta; hostil a, dat. 2 odioso; detestável; abominável 3 triste; sombrio; taciturno ♦ στυγνόν adv. 4 tristemente. 〈στύγος〉</p></section></article>\n<article id=\"entry-dgp-37603\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στυγνότης, ητος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1453 na letra σ · nº geral 37603</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tristeza 2 aspecto sombrio. 〈στυγνός〉</p></section></article>\n<article id=\"entry-dgp-37604\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στύγος, εος-ους (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1454 na letra σ · nº geral 37604</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ódio; aversão 2 pena; tristeza 3 objeto de ódio; abominação.</p></section></article>\n<article id=\"entry-dgp-37605\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στυλίς, ίδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1455 na letra σ · nº geral 37605</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pequena coluna 2 mastro pequeno na popa do navio 3 Anat. cartilagem que separa as narinas. 〈στῦλος〉</p></section></article>\n<article id=\"entry-dgp-37606\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στῦλος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1456 na letra σ · nº geral 37606</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 coluna 2 sustentáculo; apoio 3 poste; estaca de madeira para sustentar tendas.</p></section></article>\n<article id=\"entry-dgp-37607\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Στυμφάλιος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1457 na letra σ · nº geral 37607</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de Estínfalo. 〈Στύμφαλος〉</p></section></article>\n<article id=\"entry-dgp-37608\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στυμφαλίς, ίδος</h1><div class=\"entry-meta\"><span>DGP · ordem 1458 na letra σ · nº geral 37608</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) de Estínfalo (lago).</p></section></article>\n<article id=\"entry-dgp-37609\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Στύμφαλος, ου (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1459 na letra σ · nº geral 37609</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Estínfalo, cidade e montanha da Arcádia.</p></section></article>\n<article id=\"entry-dgp-37610\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Στυμφήλιος, Στυμφηλίς, Στύμφηλος</h1><div class=\"entry-meta\"><span>DGP · ordem 1460 na letra σ · nº geral 37610</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = Στυμφάλιος, Στυμφαλίς, Στύμφαλος.</p></section></article>\n<article id=\"entry-dgp-37611\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στύξ, στυγός (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1461 na letra σ · nº geral 37611</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 frio; glacial; arrepio 2 coisa arrepiante; objeto horrível 3 horror; abominação ♦ ἡ Στύξ 4 Estige, rio da Arcádia, de águas glaciais 5 Estige, n. de rio dos infernos e da ninfa desse rio 6 monstro, ref. a pessoa.</p></section></article>\n<article id=\"entry-dgp-37612\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στύξαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1462 na letra σ · nº geral 37612</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. aor. de στυγέω.</p></section></article>\n<article id=\"entry-dgp-37613\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στυππεῖον</h1><div class=\"entry-meta\"><span>DGP · ordem 1463 na letra σ · nº geral 37613</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e στυπεῖον, ου (τό) fibra de linho ou de cânhamo; estopa. 〈στύφω〉</p></section></article>\n<article id=\"entry-dgp-37614\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στυπτηρία, ας</h1><div class=\"entry-meta\"><span>DGP · ordem 1464 na letra σ · nº geral 37614</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. στυπτηρίη, ης (ἡ) alume, substância adstringente. 〈στύφω〉</p></section></article>\n<article id=\"entry-dgp-37615\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στυράκιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1465 na letra σ · nº geral 37615</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dim. de στύραξ1 e 2.</p></section></article>\n<article id=\"entry-dgp-37616\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στύραξ1, ακος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1466 na letra σ · nº geral 37616</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 extremidade; ponta de lança 2 lança; pique.</p></section></article>\n<article id=\"entry-dgp-37617\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στύραξ2, ακος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1467 na letra σ · nº geral 37617</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">estoraque, a resina e o arbusto que a produz.</p></section></article>\n<article id=\"entry-dgp-37618\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στυφελίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1468 na letra σ · nº geral 37618</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres., impf., aor. ἐστυφέλιξα; pas. só pres. e impf.) 1 bater, golpear fortemente 2 derrubar 3 expulsar 4 fazer dispersar 5 Medic. manejar com rudeza 6 tratar rudemente; maltratar; machucar. 〈στυφελός〉</p></section></article>\n<article id=\"entry-dgp-37619\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στυφελός, ή</h1><div class=\"entry-meta\"><span>DGP · ordem 1469 na letra σ · nº geral 37619</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ός, όν = στυφλός. 〈στύφω〉</p></section></article>\n<article id=\"entry-dgp-37620\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στυφλός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1470 na letra σ · nº geral 37620</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 acre; ácido 2 firme; forte; duro 3 duro; cruel. 〈στύφω〉</p></section></article>\n<article id=\"entry-dgp-37621\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στυφότης, ητος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1471 na letra σ · nº geral 37621</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 densidade; consistência; espessura 2 severidade; acrimônia. 〈στύφω〉</p></section></article>\n<article id=\"entry-dgp-37622\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στύφω</h1><div class=\"entry-meta\"><span>DGP · ordem 1472 na letra σ · nº geral 37622</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. στύψω, aor. ἔστυψα; perf. méd. pas. ἔστυμμαι, aor. pas. ἐστύφθην) 1 contrair; apertar 2 intr. ser adstringente; ter sabor acre 3 Medic. ter retenção urinária 4 ser inflexível, duro ♦ méd. 5 Medic. ter prisão de ventre; constipar-se.</p></section></article>\n<article id=\"entry-dgp-37623\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στύω</h1><div class=\"entry-meta\"><span>DGP · ordem 1473 na letra σ · nº geral 37623</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. στύσω, aor. ἔστυσα, perf. ἔστυκα) at. e méd. ter uma ereção; ter o pênis ereto.</p></section></article>\n<article id=\"entry-dgp-37624\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Στωϊκός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1474 na letra σ · nº geral 37624</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 da escola do Pórtico; dos estóicos: ἡ στωϊκὴ αἵρεσις, σχολή ou φιλοσοφία a seita, a escola ou a filosofia estóica ♦ ὁ Στωϊκός 2 filósofo estóico. 〈στοά〉</p></section></article>\n<article id=\"entry-dgp-37625\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στωμυλία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1475 na letra σ · nº geral 37625</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tagarelice; loquacidade; conversa fiada. 〈στωμύλος〉</p></section></article>\n<article id=\"entry-dgp-37626\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στωμύλλω</h1><div class=\"entry-meta\"><span>DGP · ordem 1476 na letra σ · nº geral 37626</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres.) at. e méd. (pres. e aor.) 1 tagarelar ♦ méd. 2 deblaterar contra alguém, εἰς e ac. 〈στωμύλος〉</p></section></article>\n<article id=\"entry-dgp-37627\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στώμυλμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1477 na letra σ · nº geral 37627</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tagarelice 2 pessoa tagarela.</p></section></article>\n<article id=\"entry-dgp-37628\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">στωμύλος, ος</h1><div class=\"entry-meta\"><span>DGP · ordem 1478 na letra σ · nº geral 37628</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e η, ον 1 tagarela; loquaz; eloquente; fluente ♦ τὸ στωμύλον 2 linguagem espirituosa ou alegre. 〈στόμα〉</p></section></article>\n<article id=\"entry-dgp-37629\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σύ</h1><div class=\"entry-meta\"><span>DGP · ordem 1479 na letra σ · nº geral 37629</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(sing. nom. σύ, gen. σοῦ, dat. σοί, ac. σέ; pl. nom. ὑμεῖς, gen. ὑμῶν, dat. ὑμῖν, ac. ὑμᾶς; dual nom. ac. σφῶϊ e σφώ, gen. dat. σφῶϊν e σφῷν) pron. pes. de 2a pes. tu; pl. vós.</p></section></article>\n<article id=\"entry-dgp-37630\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σύβαρις, εως</h1><div class=\"entry-meta\"><span>DGP · ordem 1480 na letra σ · nº geral 37630</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ιδος, jôn. ιος (ἡ) 1 Síbaris, n. de cidade da Magna Grécia, renomada pela frouxidão dos costumes, e n. de m. ♦ ἡ σύβαρις 2 luxo; indolência.</p></section></article>\n<article id=\"entry-dgp-37631\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Συβαρίτης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1481 na letra σ · nº geral 37631</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">sibarita; habitante ou oriundo de Síbaris. 〈Σύβαρις〉</p></section></article>\n<article id=\"entry-dgp-37632\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συβαριτικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1482 na letra σ · nº geral 37632</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de sibarita. 〈Σύβαρις〉</p></section></article>\n<article id=\"entry-dgp-37633\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Συβαρῖτις, ιδος</h1><div class=\"entry-meta\"><span>DGP · ordem 1483 na letra σ · nº geral 37633</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) = Συβαρίτης.</p></section></article>\n<article id=\"entry-dgp-37634\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συβόσιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1484 na letra σ · nº geral 37634</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 manada de porcos; vara 2 chiqueiro. 〈σῦς, βόσκω〉</p></section></article>\n<article id=\"entry-dgp-37635\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συβώτης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1485 na letra σ · nº geral 37635</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">guardador de porcos; porqueiro. 〈σῦς, βόσκω〉</p></section></article>\n<article id=\"entry-dgp-37636\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συβωτικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1486 na letra σ · nº geral 37636</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de porqueiro. 〈συβώτης〉</p></section></article>\n<article id=\"entry-dgp-37637\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συγγάμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1487 na letra σ · nº geral 37637</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 unido em casamento; casado com, dat. 2 adquirido pelo casamento (parente) 3 que partilha com outrem, dat., a condição de cônjuge ♦ ὁ, ἡ συγγάμος 4 esposo; esposa. 〈σύν, γάμος〉</p></section></article>\n<article id=\"entry-dgp-37638\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συγγένεια,</h1><div class=\"entry-meta\"><span>DGP · ordem 1488 na letra σ · nº geral 37638</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. ant. ξυγγένεια, ας (ἡ) 1 parentesco com alguém, πρός e ac. 2 parentesco; conjunto de parentes; família 3 membro de uma família; parente 4 pl. as famílias 5 classe; gênero; espécie. 〈συγγενής〉</p></section></article>\n<article id=\"entry-dgp-37639\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συγγενής,</h1><div class=\"entry-meta\"><span>DGP · ordem 1489 na letra σ · nº geral 37639</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. ant. ξυγγενής, ής, ές 1 nascido com; que vem de nascimento; inato; natural; congênito: συγγενεῖς μῆνες sóf. os meses nascidos comigo, i.e., nos quais comecei minha vida, συγγενεῖς τρίχες os cabelos que nascem com o homem 2 da mesma origem; da mesma família; consangüíneo; parente de alguém, dat. ou gen. 3 parentes; de parente: σ. χείρ sóf. mão de um parente, σ. γάμος ésql. casamento entre parentes 4 na Pérsia, parente; familiar, título honorífico conferido pelo rei 5 que tem afinidade com; semelhante ou análogo a alguém ou a algo, dat. ou gen. ♦ ὁ, ἡ συγγενής 6 parente; parenta ♦ οἱ συγγενεῖς 7 os parentes ♦ τὸ συγγενές 8 parentesco 9 parentesco (entre populações da mesma origem ♦ τὰ συγγενῆ 10 coisas da mesma espécie. 〈σύν, γένος〉</p></section></article>\n<article id=\"entry-dgp-37640\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συγγενικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1490 na letra σ · nº geral 37640</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 congênito ou hereditário (doença) 2 que vem de nascimento; natural; inato 3 de parente; que concerne aos parentes 4 que pertence a uma estirpe, a uma família 5 que tem afinidade com; do mesmo tipo de, πρός e ac. 〈συγγενής〉</p></section></article>\n<article id=\"entry-dgp-37641\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συγγενίς, ίδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1491 na letra σ · nº geral 37641</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">parente. 〈συγγενής〉</p></section></article>\n<article id=\"entry-dgp-37642\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συγγέρων, οντος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1492 na letra σ · nº geral 37642</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">companheiro de velhice.</p></section></article>\n<article id=\"entry-dgp-37643\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συγγέωργος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1493 na letra σ · nº geral 37643</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">companheiro de trabalho na lavoura. 〈σύν, γεωργός〉</p></section></article>\n<article id=\"entry-dgp-37644\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συγγηράσκω</h1><div class=\"entry-meta\"><span>DGP · ordem 1494 na letra σ · nº geral 37644</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. συγγηράσομαι) envelhecer junto com, dat.</p></section></article>\n<article id=\"entry-dgp-37645\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συγγίγνομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1495 na letra σ · nº geral 37645</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. ant. ξυγγίγνομαι (fut. συγγενήσομαι, aor.2 συνεγενόμην) 1 nascer com, dat. 2 estar junto; estar com; travar relações com, dat.: οἱ συγγινόμενοι xen. os colegas, κατ᾽ ἡλικίην τε καὶ φιλότητα εἰλαδὸν συγγίγνεσθαι ἐς πόσιν her. reunir-se para beber em grupo, conforme a idade ou as relações de amizade, χαλεποὶ καὶ συγγενέσθαι, οὐδὲν ἐθέλοντες ἐπαινεῖν ἄλλ᾽ ἢ τὸ πλουτον plat. até a convivência com eles é difícil, pois só querem louvar a riqueza, νικᾶν ἅπαντας οἷσπερ ἂν συγγένηται ar. vencer a todos com quem travar relações 3 frequentar (um mestre), dat.: διαφθείρων τοὺς συγγιγνομένους plat. corrompendo os discípulos, οὐκ ἀκηκόατε σύ τε καὶ Σιμμίας περὶ τῶν τοιούτων Φιλολάῳ συγγεγονότες; plat. tu e Símias não ouvistes a respeito de tais assuntos quando frequentastes Filolau? 4 viver com; estar em contato com; ter o hábito de, dat. 5 ter relações sexuais com, dat.: ἔτι οἷός τε εἶ γυναικὶ συγγίγνεσθαι; plat. ainda és capaz de estar com uma mulher? 6 vir em auxílio de; ajudar; socorrer, dat.: μόνον Κράτος τε καὶ ∆ίκη σὺν τῷ τρίτῳ πάντων μεγίστῳ Ζηνὶ συγγένοιτό μοι ésql. que venham em meu auxílio apenas Poder e Justiça, junto com o terceiro, Zeus, o maior de todos 7 entrar em contato com; conhecer, dat.: σοὶ ξυγγενέσθαι βουλομένω ar. [nós dois viemos] querendo entrar em contato contigo.</p></section></article>\n<article id=\"entry-dgp-37646\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συγγιγνώσκω,</h1><div class=\"entry-meta\"><span>DGP · ordem 1496 na letra σ · nº geral 37646</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. συγγινώσκω (fut. συγγνώσομαι, aor.2 συνέγνων) 1 reconhecer seu erro: συγγνοὺς χρή­σο­μαι τῇ ἐκείνου γνώμῃ her. após reconhecer meu erro, adotarei a opinião dele 2 conhecer juntamente com; ter conhecimento de algo com outros 3 ter conhecimeto de uma conspiração em cumplicidade com alguém, dat.: οἱ συνεγνωκότες AP. os conspiradores 4 reconhecer; compreender a partir de, ἀπό, ἐκ e gen., que, or. (ὅτι) ♦ at. e méd. 5 ser da mesma opinião; estar de acordo com; concordar com alguém, dat., em alguma coisa, ac. ou πρός ac., ou inf.: μετὰ πολλῶν τὴν ἁμαρτίαν ξυνέγνωσαν tuc. partilharam o erro com muitas pessoas, τοὺς πρεσβυτέρους ἀδελφεοὺς συγγνόντας τὴν βασιληίην πᾶσαν παραδοῦναι τῷ νεωτάτῳ her. [dizem que] os irmãos mais velhos concordaram em entregar o poder real total ao mais novo, οἱ δὲ οὐ συγγινωσκόμενοι ἀποκτείναντες κατευωχέονται her. mas eles, não sendo do mesmo parecer, após matar [o doente], regalam-se 6 concordar; reconhecer; admitir algo, ac., inf. part. ou ὡς: συνέγνω ἑωυτοῦ εἶναι τὴν ἁμαρτάδα καὶ οὐ τοῦ θεοῦ her. reconheceu que o equívoco era seu e não do deus, παθόντες ἂν ξυγγνοῖμεν ἡμαρτηκότες sóf. ao padecer, reconheceríamos somos culpados, συγγινωσκόμενος ἀνθρώπων εἶναι τῶν αὐτὸς ᾔδεε βαρυσυμφορώτατος her. reconhecendo ser o mais desafortunado dos homens que conhecia 7 ter consciência de, com part. no nom. ou no dat., ou inf.: συγγινώσκομεν αὐτοῖσι ἡμῖν οὐ ποιήσασι ὀρθῶς her. temos consciência de não ter agido bem, συνέγνωσαν αὐτοὶ σφίσιν ὡς ἠδικηκότες LÍS. tiveram consciência de ter cometido uma injustiça, συνεγινώσκετο ἑωυτῷ οὐκέτι εἶναι δυνατὸς τὰ πράγματα ἐπορᾶν her. tinha consciência de que já não era capaz de controlar os assuntos do governo 8 perdoar algo, ac. ou gen. ou dat., a alguém, dat.: συγγίγνωσκέ μοι plat. perdoa-me, σύγγνωθι ἡμῖν τοῖς λελεγμένοις eur. perdoai-nos por nossas palavras, οὔτε ὁ συγγινωσόμενός τοι πάρα her. nem está presente alguém que vá perdoar-te.</p></section></article>\n<article id=\"entry-dgp-37647\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συγγίνομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1497 na letra σ · nº geral 37647</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = συγγίγνομαι.</p></section></article>\n<article id=\"entry-dgp-37648\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συγγινώσκω</h1><div class=\"entry-meta\"><span>DGP · ordem 1498 na letra σ · nº geral 37648</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = συγγιγνώσκω.</p></section></article>\n<article id=\"entry-dgp-37649\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σύγγνοια,</h1><div class=\"entry-meta\"><span>DGP · ordem 1499 na letra σ · nº geral 37649</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. ant. ξύγγνοια, ας (ἡ) perdão. 〈συγγιγνώσκω〉</p></section></article>\n<article id=\"entry-dgp-37650\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συγγνώμη,</h1><div class=\"entry-meta\"><span>DGP · ordem 1500 na letra σ · nº geral 37650</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. ant. ξυγγνώμη, ης (ἡ) 1 perdão; desculpa; escusa a alguém, dat., por algo, gen. ou ὑπέρ e gen., da parte de alguém, παρά e gen.: συγγνώμην ἔχειν her., ποιήσασθαι her., διδόναι pol., νέμειν paus., σ. ἀπονέμειν luc. conceder perdão, perdoar, συγγνώμην αἰτεῖσθαι plat. pedir perdão, συγγνώμης τυγχάνειν xen., λαμβάνειν tuc. alcançar perdão 2 coisa perdoável: συγγνώμη ἐστί é coisa perdoável, com part., or. inf. ou or. conj. (εἰ), τούτων μὴ ἀπεχομένῳ σοι ἔσται πολλὴ συγγνώμη plat. será coisa bem perdoável se não te absténs dessas coisas, τοὺς μὲν Ἀθηναίους ταῦτα πλεονεκτεῖν πολλὴ ξυγγνώμη tuc. é coisa perdoável que os atenienses tenham essas ambições 3 indulgência; concessão; permissão: τοῦτο δὲ λέγω κατὰ συγγνώμην οὐ κατ᾽ ἐπιταγήν N.T. digo isso como concessão e não como mandamento. 〈συγγιγνώσκω〉</p></section></article>\n<article id=\"entry-dgp-37651\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συγγνωμονικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1501 na letra σ · nº geral 37651</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 indulgente; compreensivo 2 perdoável. 〈συγγνώμων〉</p></section></article>\n<article id=\"entry-dgp-37652\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συγγνωμοσύνη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1502 na letra σ · nº geral 37652</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 indulgência 2 perdão. 〈συγ­γνώμων〉</p></section></article>\n<article id=\"entry-dgp-37653\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συγγνώμων,</h1><div class=\"entry-meta\"><span>DGP · ordem 1503 na letra σ · nº geral 37653</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. ant. ξυγγνώμων, ων, ον gen. ονος 1 que é da mesma opinião que alguém, dat., acerca de algo, gen.; que está de acordo; concorde 2 que perdoa; indulgente; clemente para com alguém, dat., a respeito de algo, gen. 3 favorável a que alguém, dat. e inf.: ξυγ­γνώμονες δὲ ἔστε τῆς ἀδικίας κολάζεσθαι τοῖς ὑπάρχουσι προτέροις tuc. sede favoráveis a que sejam punidos os primeiros a praticar injustiça 4 perdoável ♦ τὸ ξύγγνωμον 5 indulgência. 〈συγγιγνώσκω〉</p></section></article>\n<article id=\"entry-dgp-37654\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συγγνωστός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1504 na letra σ · nº geral 37654</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">perdoável; desculpável: συγγνωστόν ἐστι ou συγγνωστά ἐστι com inf. é coisa perdoável, αὐτοῖς συγγνωστόν com part. plut. é coisa perdoável para eles, συγγνωστός com part. plut. é perdoável. 〈συγγιγνώσκω〉</p></section></article>\n<article id=\"entry-dgp-37655\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συγγομφόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1505 na letra σ · nº geral 37655</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fixar junto com pregos.</p></section></article>\n<article id=\"entry-dgp-37656\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σύγγονος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1506 na letra σ · nº geral 37656</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de nascimento comum; consanguíneo de, dat. 2 inato; natural; congênito 3 da mesma região; nativo ♦ ὁ, ἡ σύγγονος 4 irmão; irmã 5 pl., parentes; primos. 〈συγγίγνομαι〉</p></section></article>\n<article id=\"entry-dgp-37657\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σύγγραμμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1507 na letra σ · nº geral 37657</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 composição escrita; obra; tratado 2 obra em prosa; discurso escrito 3 Jur. regulamento; estatuto; cláusula de lei 4 receita médica. 〈συγγράφω〉</p></section></article>\n<article id=\"entry-dgp-37658\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συγγραφεύς,</h1><div class=\"entry-meta\"><span>DGP · ordem 1508 na letra σ · nº geral 37658</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. ant. ξυγγραφεύς, έως (ὁ) 1 prosador 2 historiador 3 escritor; autor 4 Jur., pl., em Atenas, comissões legislativas. 〈συγγράφω〉</p></section></article>\n<article id=\"entry-dgp-37659\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συγγραφή,</h1><div class=\"entry-meta\"><span>DGP · ordem 1509 na letra σ · nº geral 37659</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. ant. ξυγγραφή, ῆς (ἡ) 1 ação de compor; descrição; exposição 2 dados para composição 3 escrito em prosa 4 obra de história 5 tratado; ata; contrato 6 contrato comercial ou de seguro marítimo 7 Jur. projeto de lei 8 documento. 〈συγγράφω〉</p></section></article>\n<article id=\"entry-dgp-37660\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συγγραφικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1510 na letra σ · nº geral 37660</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">concernente à redação de obra em prosa. 〈συγγραφή〉</p></section></article>\n<article id=\"entry-dgp-37661\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συγγραφικῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 1511 na letra σ · nº geral 37661</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. em termos precisos como os de um contrato; com precisão.</p></section></article>\n<article id=\"entry-dgp-37662\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συγγράφω,</h1><div class=\"entry-meta\"><span>DGP · ordem 1512 na letra σ · nº geral 37662</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. ant. ξυγγράφω (fut. συγγράψω, aor. συνέγραψα) 1 representar com ou junto 2 representar 3 descrever com precisão 4 compor; redigir 5 compor uma obra em prosa ou em verso: συμβουλὴν περὶ βίου σ. plat. escrever conselho sobre a vida, i.e., compor obras que aconselham como viver 6 escrever em prosa: ξυνέγραψε τὸν πόλεμον τῶν Πελοποννησίων καὶ Ἀθηναίων tuc. escreveu a guerra dos peloponésios e atenienses 7 compor discurso 8 Jur. redigir projeto de lei 9 reunir em um código as leis escritas 10 inscrever com: συγγεγραμμένοι πατέρες plut. pais conscritos, senadores, em Roma ♦ méd. 11 redigir; escrever 12 compor (discurso) 13 redigir uma emenda para um decreto 14 Jur. redigir (documentos públicos ou privados): οἱ συγγραφόμενοι plat. os redatores de projetos de lei 15 fazer um contrato escrito; estabelecer por escrito algo, ac., a respeito de, περί e gen., em vista de, πρός e ac.: συγγράφεσθαι ἐς ἐμπόριον dem. estabelecer um contrato em vista do mercado, σ. εἰρήνην πρός τινα ISÓCR. concluir, redigir um tratado de paz com alguém, σ. γάμον plut. redigir um contrato de casamento, ὁ συγγεγραμένος aquele que assumiu um compromisso por escrito 16 assinar um tratado; estabelecer um acordo.</p></section></article>\n<article id=\"entry-dgp-37663\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συγγυμνάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1513 na letra σ · nº geral 37663</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 exercitar, treinar com ou junto ou intensamente ♦ méd. 2 exercitar-se com ♦ pas. 3 ser ou tornar-se experiente em, dat.</p></section></article>\n<article id=\"entry-dgp-37664\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συγγυμνασία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1514 na letra σ · nº geral 37664</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">exercício coletivo. 〈συγγυμνάζω〉</p></section></article>\n<article id=\"entry-dgp-37665\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συγγυμναστής, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1515 na letra σ · nº geral 37665</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">companheiro de exercício. 〈συγγυμνάζω〉</p></section></article>\n<article id=\"entry-dgp-37666\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σύγε</h1><div class=\"entry-meta\"><span>DGP · ordem 1516 na letra σ · nº geral 37666</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">σύ γε.</p></section></article>\n<article id=\"entry-dgp-37667\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συγκαθαγίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1517 na letra σ · nº geral 37667</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 em sacrifício, destruir pelo fogo uma coisa, ac., junto com outra, dat.; consagrar com 2 ajudar a purificar.</p></section></article>\n<article id=\"entry-dgp-37668\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συγκαθαιρέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1518 na letra σ · nº geral 37668</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. συγκαθαιρήσω, aor.2 συγκαθεῖλον) 1 abater ou destruir com ou junto; cooperar na derrubada de, ac.: ξυγκαθελοῦσαι τὸν βάρβαρον tuc. tendo [as cidades] participado da vitória contra o bárbaro 2 depositar algo, ac., com a ajuda de, dat. 3 colaborar com alguém, dat., na conquista de, ac.: πέντε σφι ἀγῶνας τοὺς μεγίστους συγκαταιρέει her. colabora com eles [os espartanos] na conquista de cinco vitórias importantíssimas.</p></section></article>\n<article id=\"entry-dgp-37669\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συγκαθαρμόζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1519 na letra σ · nº geral 37669</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ajudar a vestir um morto para sepultá-lo 2 ajudar a tratar os ferimentos de um morto.</p></section></article>\n<article id=\"entry-dgp-37670\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συγκαθέζομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1520 na letra σ · nº geral 37670</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. συγκαθεδοῦμαι) 1 sentar-se com ou junto 2 agachar-se.</p></section></article>\n<article id=\"entry-dgp-37671\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συγκαθείργω</h1><div class=\"entry-meta\"><span>DGP · ordem 1521 na letra σ · nº geral 37671</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">encerrar alguém, ac., junto de, dat.</p></section></article>\n<article id=\"entry-dgp-37672\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συγκαθέλκω,</h1><div class=\"entry-meta\"><span>DGP · ordem 1522 na letra σ · nº geral 37672</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. ant. ξυγκαθέλγω (aor. συγκαθείλκυσα) arrastar com ou junto.</p></section></article>\n<article id=\"entry-dgp-37673\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συγκαθεύδω</h1><div class=\"entry-meta\"><span>DGP · ordem 1523 na letra σ · nº geral 37673</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dormir com; ter relações sexuais com, dat.</p></section></article>\n<article id=\"entry-dgp-37674\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συγκάθημαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1524 na letra σ · nº geral 37674</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres.) 1 estar assentado com ou ao lado de 2 sentar junto em reunião, em conselho: σ. περὶ εἰρήνης tuc. estar em assembléia para tratar da paz 3 morar com; coabitar 4 estar sentado ou acocorado.</p></section></article>\n<article id=\"entry-dgp-37675\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συγκαθιδρύω</h1><div class=\"entry-meta\"><span>DGP · ordem 1525 na letra σ · nº geral 37675</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">consagrar uma fundação a um deus, ac., juntamente com outro, dat.</p></section></article>\n<article id=\"entry-dgp-37676\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συκαθιερόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1526 na letra σ · nº geral 37676</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">consagrar ao mesmo tempo ou junto.</p></section></article>\n<article id=\"entry-dgp-37677\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συγκαθίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1527 na letra σ · nº geral 37677</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. συγκαθιζήσω, aor. συνεκάθισα, perf. συγκεκάθικα) 1 bíbl. fazer sentar junto 2 bíbl., intr. sentar-se junto em audiência pública ♦ méd. 3 sentar-se em reunião; reunir-se para deliberação 4 (pessoa) acocorar-se 5 (quadrúpede) recolher as patas para se deitar; abaixar-se.</p></section></article>\n<article id=\"entry-dgp-37678\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συγκαθίημι</h1><div class=\"entry-meta\"><span>DGP · ordem 1528 na letra σ · nº geral 37678</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. συγκαθήσω) 1 colocar, depositar ao mesmo tempo ou juntamente 2 ceder; submeter-se: εἰς τῶν ἐγγὺς οὐδὲν αὑτὴν συγκαθιεῖσα plat. não se abaixando para nada do que está próximo 3 abaixar-se; estender-se, ἐπί e ac. 4 condescender com alguém, dat., em algo, dat. ou εἰς e ac.: οἱ δὲ γέροντες συγκαθιέντες τοῖς νέοις plat. os velhos, condescendentes com os jovens, σ. τῇ τιμῇ AT. ceder no preço, abaixar o preço.</p></section></article>\n<article id=\"entry-dgp-37679\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συγκαθίστημι</h1><div class=\"entry-meta\"><span>DGP · ordem 1529 na letra σ · nº geral 37679</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. συγκαταστήσω) 1 ajudar a pôr em condições, a constituir, a estabelecer, a consolidar 2 ajudar a reorganizar, a realizar 3 pôr em segurança 4 ajudar a tratar, a curar (doença) ♦ intr. e méd. 5 afrontar; medir-se com; chegar a vias de fato com alguém, dat. ou πρός e ac. ou μετά e gen.: οἱ συγκαθεστῶτες os adversários.</p></section></article>\n<article id=\"entry-dgp-37680\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συγκαθοσιόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1530 na letra σ · nº geral 37680</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">consagrar com ou junto.</p></section></article>\n<article id=\"entry-dgp-37681\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συγκαίω,</h1><div class=\"entry-meta\"><span>DGP · ordem 1531 na letra σ · nº geral 37681</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. συγκάω, át. ant. ξυγκάω (fut. συγκαύσω) 1 queimar ou inflamar inteiramente 2 intr. inflamar-se; aquecer demais.</p></section></article>\n<article id=\"entry-dgp-37682\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συγκακοπαθέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1532 na letra σ · nº geral 37682</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. sofrer com, dat.</p></section></article>\n<article id=\"entry-dgp-37683\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συγκακουχέομαι-οῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1533 na letra σ · nº geral 37683</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. sofrer maus-tratos junto com, dat.</p></section></article>\n<article id=\"entry-dgp-37684\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συγκαλέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1534 na letra σ · nº geral 37684</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. συγκαλέσω, át. συγκαλῶ, aor. συνεκάλεσα) 1 chamar alguém, ac., ao mesmo tempo que outra, dat. 2 convocar; intimar alguém, ac., para, inf. ♦ méd. 3 convocar 4 convidar uma pessoa, ac., juntamente com outra, dat.</p></section></article>\n<article id=\"entry-dgp-37685\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συγκαλινδέομαι-οῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1535 na letra σ · nº geral 37685</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">rolar junto.</p></section></article>\n<article id=\"entry-dgp-37686\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συγκαλυπτέος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1536 na letra σ · nº geral 37686</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de συγκαλύπτω.</p></section></article>\n<article id=\"entry-dgp-37687\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συγκαλυπτός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1537 na letra σ · nº geral 37687</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">recoberto de, dat. 〈συγκαλύπτω〉</p></section></article>\n<article id=\"entry-dgp-37688\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συγκαλύπτω</h1><div class=\"entry-meta\"><span>DGP · ordem 1538 na letra σ · nº geral 37688</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cobrir inteiramente; envolver; ocultar ♦ intr. e méd. 2 cobrir-se.</p></section></article>\n<article id=\"entry-dgp-37689\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συγκάμνω</h1><div class=\"entry-meta\"><span>DGP · ordem 1539 na letra σ · nº geral 37689</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. συγκαμοῦμαι, aor.2 συνέκαμον) 1 trabalhar ou fazer esforço com alguém, dat. 2 socorrer; colaborar com; assistir, dat. 3 participar do sofrimento de alguém ou por algo, dat.</p></section></article>\n<article id=\"entry-dgp-37690\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συγκάμπτω,</h1><div class=\"entry-meta\"><span>DGP · ordem 1540 na letra σ · nº geral 37690</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. ant. ξυγκάμπτω (aor. pas. συνεκάμφθην, perf. part. συγκεκαμμένος) 1 contrair ou juntar sobre si dobrando (pernas, braços, espinha); flectir; flexionar 2 intr. curvar-se ♦ méd. 3 dobrar-se.</p></section></article>\n<article id=\"entry-dgp-37691\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συγκασιγνήτη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1541 na letra σ · nº geral 37691</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">irmã.</p></section></article>\n<article id=\"entry-dgp-37692\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σύγκασις, ιος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1542 na letra σ · nº geral 37692</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">συγκασιγνήτη.</p></section></article>\n<article id=\"entry-dgp-37693\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συγκαταβαίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 1543 na letra σ · nº geral 37693</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor.2 συγκατέβην) 1 descer junto ou ao mesmo tempo, dat. ou ἅμα e dat. 2 (divindade) descer em socorro; descer para auxiliar 3 atirar-se a, εἰς e ac.: σ. εἰς κίνδυνον pol. expor-se a um perigo, σ. εἰς πόλεμον pol. lançar-se a uma guerra 4 concordar com algo, εἰς e ac. 5 condescender; consentir 6 ceder no preço de algo.</p></section></article>\n<article id=\"entry-dgp-37694\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συγκαταβάλλω</h1><div class=\"entry-meta\"><span>DGP · ordem 1544 na letra σ · nº geral 37694</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gastar junto ou com; contribuir com algo, ac.</p></section></article>\n<article id=\"entry-dgp-37695\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συγκαταβιόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1545 na letra σ · nº geral 37695</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">passar a vida com; conviver com, dat.</p></section></article>\n<article id=\"entry-dgp-37696\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συγκαταγηράσκω</h1><div class=\"entry-meta\"><span>DGP · ordem 1546 na letra σ · nº geral 37696</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ficar velho; envelhecer junto ou com algo ou alguém, dat. 2 envelhecer; ficar velho 3 (doença) entranhar-se.</p></section></article>\n<article id=\"entry-dgp-37697\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συγκαταγομφόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1547 na letra σ · nº geral 37697</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fixar com prego junto a algo.</p></section></article>\n<article id=\"entry-dgp-37698\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συγκατάγω</h1><div class=\"entry-meta\"><span>DGP · ordem 1548 na letra σ · nº geral 37698</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ajudar a trazer de volta; contribuir para restabelecer (regime político) 2 fazer descer ao mesmo tempo.</p></section></article>\n<article id=\"entry-dgp-37699\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συγκαταδιώκω,</h1><div class=\"entry-meta\"><span>DGP · ordem 1549 na letra σ · nº geral 37699</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. ant. ξυγκαταδιώκω perseguir junto ou ao mesmo tempo.</p></section></article>\n<article id=\"entry-dgp-37700\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συγκαταδουλόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1550 na letra σ · nº geral 37700</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">at. e méd. 1 ajudar alguém, dat., a submeter 2 ajudar a escravizar.</p></section></article>\n";
